import numpy as np
from sklearn.feature_extraction.text import TfidfVectorizer
import re

def task_func(example_str):
    # Remove text enclosed in square brackets, handling potential newlines inside brackets
    text_outside = re.sub(r'\[[^\]]*\]', '', example_str)

    # Return empty dictionary if string is empty or contains only whitespace
    if not text_outside.strip():
        return {}

    vectorizer = TfidfVectorizer()
    try:
        # Fit transform on the single remaining string
        tfidf_matrix = vectorizer.fit_transform([text_outside])
    except ValueError:
        # TfidfVectorizer raises a ValueError if the vocabulary is empty (e.g., only stop words or punctuation)
        return {}

    feature_names = vectorizer.get_feature_names_out()
    scores = tfidf_matrix.toarray()[0]

    # Return a dictionary mapping terms to their TF-IDF scores, cast to Python floats
    return {word: float(score) for word, score in zip(feature_names, scores)}
